import React, { CSSProperties } from 'react';
import { Box, atoms, theme } from '@fiverr-private/theme';
import { Typography } from '@fiverr-private/typography';
import { getProgressColors, getProgressPercent } from '../ProgressLine/helpers';
import { ProgressCircleProps } from './types';
import { PATH } from './constants';
import { getProgressBackgroundStyle } from './helpers';

const ProgressCircle = ({
  percent = 0,
  progressColor = 'default',
  trackColor = 'default',
  showScore,
  dataTrackTag = 'progress_circle',
  dataTrackValue,
}: ProgressCircleProps) => {
  const { progressBackgroundColor, trackBackgroundColor } = getProgressColors({ progressColor, trackColor });
  const progress = getProgressPercent(percent);

  const trackStyle: CSSProperties = {
    strokeDasharray: 205,
    strokeDashoffset: 0,
    stroke: theme.colors[trackBackgroundColor],
    strokeWidth: 4,
  };

  const svgStyle: CSSProperties = {
    zIndex: 2,
    top: 0,
    left: 0,
    fill: 'none',
  };

  return (
    <Box
      as="div"
      role="progressbar"
      aria-valuenow={percent}
      aria-valuemin={0}
      aria-valuemax={100}
      display="inlineFlex"
      justifyContent="center"
      alignItems="center"
      position="relative"
      width="64px"
      height="64px"
      color={progressBackgroundColor}
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
    >
      <svg style={svgStyle} className={atoms({ position: 'absolute' })} viewBox="-1 -1 71 71">
        <path d={PATH} style={trackStyle} />
        <path d={PATH} style={getProgressBackgroundStyle(progress, progressBackgroundColor)} />
      </svg>
      {showScore && (
        <Typography
          position="absolute"
          size="b_md"
          fontWeight="semibold"
          transform="translateX(.1em)"
        >{`${percent}%`}</Typography>
      )}
    </Box>
  );
};

ProgressCircle.display = 'ProgressCircle';
export default ProgressCircle;
