import type { CSSProperties } from 'react';
import { theme } from '@fiverr-private/theme';
import { CIRCLE_MAX } from './constants';

export const getProgressBackgroundStyle = (percent, color): CSSProperties => {
    const progress = (CIRCLE_MAX * percent) / 100;

    return {
        strokeDasharray: CIRCLE_MAX,
        strokeDashoffset: CIRCLE_MAX - progress,
        stroke: theme.colors[color],
        strokeWidth: 4,
        strokeLinecap: 'round',
    };
};
